import React, { createContext, useState, useContext, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useModal } from './ModalContext';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [orders, setOrders] = useState([]);

  const navigate = useNavigate();
  const { showModal } = useModal();

  // 🔄 Загружаем данные при загрузке приложения
  useEffect(() => {
    const loadStoredData = () => {
      try {
        setLoading(true);

        // 1. Проверяем, есть ли сохраненный токен и пользователь
        const storedToken = localStorage.getItem('luna_aurea_token');
        const storedUser = localStorage.getItem('luna_aurea_user');

        if (storedToken && storedUser) {
          try {
            // Проверяем токен (в реальном приложении проверяем с сервером)
            const tokenData = JSON.parse(atob(storedToken.split('.')[1]));
            const currentTime = Math.floor(Date.now() / 1000);

            if (tokenData.exp > currentTime) {
              // Токен действителен
              setUser(JSON.parse(storedUser));
              setToken(storedToken);
              console.log('Автоматический вход выполнен:', JSON.parse(storedUser));
            } else {
              // Токен истёк
              console.log('Токен истёк, требуется повторный вход');
              clearAuthData();
            }
          } catch (error) {
            console.error('Ошибка при проверке токена:', error);
            clearAuthData();
          }
        }

        // 2. Загружаем корзину, избранное и заказы
        const storedCart = localStorage.getItem('luna_aurea_cart');
        const storedFavorites = localStorage.getItem('luna_aurea_favorites');
        const storedOrders = localStorage.getItem('luna_aurea_orders');

        if (storedCart) {
          try {
            setCart(JSON.parse(storedCart));
          } catch (error) {
            console.error('Ошибка загрузки корзины:', error);
            localStorage.removeItem('luna_aurea_cart');
          }
        }

        if (storedFavorites) {
          try {
            setFavorites(JSON.parse(storedFavorites));
          } catch (error) {
            console.error('Ошибка загрузки избранного:', error);
            localStorage.removeItem('luna_aurea_favorites');
          }
        }

        if (storedOrders) {
          try {
            setOrders(JSON.parse(storedOrders));
          } catch (error) {
            console.error('Ошибка загрузки заказов:', error);
            localStorage.removeItem('luna_aurea_orders');
          }
        }

      } catch (error) {
        console.error('Ошибка при загрузке данных:', error);
        clearAuthData();
      } finally {
        setLoading(false);
      }
    };

    // Задержка для имитации загрузки (можно убрать)
    setTimeout(() => {
      loadStoredData();
    }, 500);
  }, []);

  // 🔄 Сохраняем изменения в localStorage
  useEffect(() => {
    if (user) {
      localStorage.setItem('luna_aurea_user', JSON.stringify(user));
    }
  }, [user]);

  useEffect(() => {
    if (token) {
      localStorage.setItem('luna_aurea_token', token);
    }
  }, [token]);

  useEffect(() => {
    localStorage.setItem('luna_aurea_cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('luna_aurea_favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    localStorage.setItem('luna_aurea_orders', JSON.stringify(orders));
  }, [orders]);

  // 🔄 Регистрация пользователя
  const register = async (username, email, password) => {
    try {
      setLoading(true);

      // Проверяем существующих пользователей
      const existingUsers = JSON.parse(localStorage.getItem('luna_aurea_registered_users') || '[]');

      // Проверка на существующий email
      const userExistsByEmail = existingUsers.some(u => u.email === email);
      if (userExistsByEmail) {
        throw new Error('Пользователь с таким email уже зарегистрирован');
      }

      // Проверка на существующее имя пользователя
      const userExistsByUsername = existingUsers.some(u => u.username === username);
      if (userExistsByUsername) {
        throw new Error('Это имя пользователя уже занято');
      }

      // Проверка пароля
      if (password.length < 6) {
        throw new Error('Пароль должен содержать минимум 6 символов');
      }

      // Создаём нового пользователя
      const newUser = {
        id: `user_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        username,
        email,
        password: btoa(password), // Простое шифрование (в реальном приложении нужен сервер)
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        role: 'user',
        avatar: `https://ui-avatars.com/api/?name=${username}&background=random&color=fff`
      };

      // Сохраняем в "базу данных" (localStorage)
      existingUsers.push(newUser);
      localStorage.setItem('luna_aurea_registered_users', JSON.stringify(existingUsers));

      // Создаём токен
      const newToken = generateToken(newUser.id);

      // Убираем пароль из данных пользователя перед сохранением в state
      const { password: _, ...userWithoutPassword } = newUser;

      // Устанавливаем состояние
      setUser(userWithoutPassword);
      setToken(newToken);

      // Показываем уведомление
      showModal('success', null, '🎉 Регистрация успешна!', `Добро пожаловать, ${username}! Теперь вы можете пользоваться всеми функциями сайта.`);

      // Записываем в лог
      console.log('Новый пользователь зарегистрирован:', userWithoutPassword);

      return { success: true, user: userWithoutPassword };

    } catch (error) {
      console.error('Ошибка регистрации:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // 🔄 Вход пользователя
  const login = async (email, password, rememberMe = false) => {
    try {
      setLoading(true);

      // Ищем пользователя в "базе данных"
      const existingUsers = JSON.parse(localStorage.getItem('luna_aurea_registered_users') || '[]');
      const userData = existingUsers.find(u => u.email === email);

      if (!userData) {
        throw new Error('Пользователь с таким email не найден');
      }

      // Проверяем пароль
      const encodedPassword = btoa(password);
      if (userData.password !== encodedPassword) {
        throw new Error('Неверный пароль');
      }

      // Убираем пароль из данных пользователя
      const { password: _, ...userWithoutPassword } = userData;

      // Создаём токен с разным сроком действия
      const tokenDays = rememberMe ? 30 : 7;
      const newToken = generateToken(userData.id, tokenDays);

      // Устанавливаем состояние
      setUser(userWithoutPassword);
      setToken(newToken);

      // Сохраняем флаг "запомнить меня"
      if (rememberMe) {
        localStorage.setItem('luna_aurea_remember_me', 'true');
      } else {
        localStorage.removeItem('luna_aurea_remember_me');
      }

      // Записываем в лог
      console.log('Пользователь вошёл в систему:', userWithoutPassword);

      return { success: true, user: userWithoutPassword };

    } catch (error) {
      console.error('Ошибка входа:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // 🔄 Быстрый вход тестового пользователя
  const quickLogin = () => {
    return login('test@example.com', '123456');
  };

  // 🔄 Выход
  const logout = () => {
    console.log('Пользователь вышел из системы');

    // Очищаем состояние
    setUser(null);
    setToken(null);

    // Очищаем localStorage (но оставляем зарегистрированных пользователей)
    localStorage.removeItem('luna_aurea_user');
    localStorage.removeItem('luna_aurea_token');
    localStorage.removeItem('luna_aurea_remember_me');

    // Перенаправляем на главную
    navigate('/');

    // Показываем уведомление
    showModal('info', null, 'Вы вышли из аккаунта', 'До новых встреч!');
  };

  // 🔄 Генерация JWT токена (упрощённая)
  const generateToken = (userId, days = 7) => {
    const header = {
      alg: 'HS256',
      typ: 'JWT'
    };

    const payload = {
      userId,
      iat: Math.floor(Date.now() / 1000), // issued at
      exp: Math.floor(Date.now() / 1000) + (days * 24 * 60 * 60) // expiration
    };

    // В реальном приложении нужно использовать секретный ключ и библиотеку для JWT
    const signature = 'luna_aurea_secret_key_2024';

    // Кодируем в base64
    const encodedHeader = btoa(JSON.stringify(header));
    const encodedPayload = btoa(JSON.stringify(payload));
    const encodedSignature = btoa(signature);

    return `${encodedHeader}.${encodedPayload}.${encodedSignature}`;
  };

  // 🔄 Очистка данных аутентификации
  const clearAuthData = () => {
    localStorage.removeItem('luna_aurea_user');
    localStorage.removeItem('luna_aurea_token');
    localStorage.removeItem('luna_aurea_remember_me');
    setUser(null);
    setToken(null);
  };

  // 🔄 Проверка, авторизован ли пользователь
  const isAuthenticated = !!user && !!token;

  // 🔄 Обновление данных пользователя
  const updateUser = (updatedData) => {
    setUser(prev => {
      const newUser = { ...prev, ...updatedData, updatedAt: new Date().toISOString() };
      return newUser;
    });

    // Обновляем в "базе данных"
    const existingUsers = JSON.parse(localStorage.getItem('luna_aurea_registered_users') || '[]');
    const updatedUsers = existingUsers.map(u => 
      u.id === user.id ? { ...u, ...updatedData, updatedAt: new Date().toISOString() } : u
    );
    localStorage.setItem('luna_aurea_registered_users', JSON.stringify(updatedUsers));
  };

  // 🔄 Функции для корзины
  const addToCart = (product) => {
    setCart(prevCart => {
      const existingItem = prevCart.find(item => item.id === product.id);

      if (existingItem) {
        return prevCart.map(item =>
          item.id === product.id
            ? { ...item, quantity: (item.quantity || 1) + 1 }
            : item
        );
      } else {
        return [...prevCart, { ...product, quantity: 1 }];
      }
    });

    showModal('success', null, 'Добавлено в корзину', `${product.name} добавлен в корзину`);
  };

  const removeFromCart = (productId) => {
    setCart(prevCart => prevCart.filter(item => item.id !== productId));
  };

  const updateCartQuantity = (productId, quantity) => {
    if (quantity < 1) {
      removeFromCart(productId);
      return;
    }

    setCart(prevCart =>
      prevCart.map(item =>
        item.id === productId ? { ...item, quantity } : item
      )
    );
  };

  const clearCart = () => {
    setCart([]);
  };

  // 🔄 Функции для избранного
  const addToFavorites = (product) => {
    setFavorites(prevFavorites => {
      if (prevFavorites.find(item => item.id === product.id)) {
        return prevFavorites;
      }
      return [...prevFavorites, product];
    });

    showModal('success', null, 'Добавлено в избранное', `${product.name} добавлен в избранное`);
  };

  const removeFromFavorites = (productId) => {
    setFavorites(prevFavorites =>
      prevFavorites.filter(item => item.id !== productId)
    );
  };

  // 🔄 Функции для заказов
  const createOrder = (orderData) => {
    const newOrder = {
      id: `ORD-${Date.now()}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      userId: user?.id,
      items: [...cart],
      total: cart.reduce((sum, item) => sum + (item.price || 0) * (item.quantity || 1), 0),
      date: new Date().toISOString(),
      status: 'pending',
      address: orderData.address,
      cardNumber: orderData.cardNumber ? `**** **** **** ${orderData.cardNumber.slice(-4)}` : 'Оплата при получении',
      contactEmail: user?.email,
      shippingMethod: 'standard',
      paymentMethod: 'card'
    };

    setOrders(prevOrders => [newOrder, ...prevOrders]);
    clearCart(); // Очищаем корзину после оформления

    return newOrder;
  };

  const cancelOrder = (orderId) => {
    setOrders(prevOrders =>
      prevOrders.map(order =>
        order.id === orderId ? { ...order, status: 'cancelled' } : order
      )
    );
  };

  const value = {
    // Основные данные
    user,
    token,
    loading,
    isAuthenticated,

    // Аутентификация
    register,
    login,
    quickLogin,
    logout,
    updateUser,

    // Корзина
    cart,
    addToCart,
    removeFromCart,
    updateCartQuantity,
    clearCart,

    // Избранное
    favorites,
    addToFavorites,
    removeFromFavorites,

    // Заказы
    orders,
    createOrder,
    cancelOrder,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
